// Web-Mercator projection matching the paths above. Returns [x, y] in viewBox units.
export function project(lon, lat) {
  const { k, tx, ty } = SWISS_MAP
  return [
    tx + k * (lon * Math.PI) / 180,
    ty - k * Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)),
  ]
}
